# owner: platform
import unittest
from datetime import date

from rosterkit.notices import absence_notice
from rosterkit.models import Mark, Student


class AbsenceNoticeTests(unittest.TestCase):
    def setUp(self):
        self.student = Student("1001", "Quillon", "Sefa", "A")

    # ---
    def mark(self, number, status, student_id="1001"):
        return Mark(student_id, date(2026, 9, number), status)

    def test_absent_days_listed_oldest_first(self):
        marks = [self.mark(10, "absent"), self.mark(3, "absent")]
        expected = (
            "Sefa Quillon was absent 2 days.\n"
            "Dates missed: 2026-09-03, 2026-09-10."
        )
        self.assertEqual(absence_notice(self.student, marks), expected)

    def test_single_day_uses_singular(self):
        expected = (
            "Sefa Quillon was absent 1 day.\n"
            "Dates missed: 2026-09-03."
        )
        notice = absence_notice(self.student, [self.mark(3, "absent")])
        self.assertEqual(notice, expected)

    def test_late_and_excused_do_not_count(self):
        marks = [self.mark(4, "late"), self.mark(5, "excused")]
        marks.append(self.mark(3, "absent"))
        expected = (
            "Sefa Quillon was absent 1 day.\n"
            "Dates missed: 2026-09-03."
        )
        self.assertEqual(absence_notice(self.student, marks), expected)

    def test_other_students_marks_are_refused(self):
        marks = [self.mark(3, "absent", student_id="1002")]
        with self.assertRaises(ValueError):
            absence_notice(self.student, marks)

    def test_no_absences_is_refused(self):
        with self.assertRaises(ValueError):
            absence_notice(self.student, [self.mark(3, "present")])

    def test_no_marks_is_refused(self):
        with self.assertRaises(ValueError):
            absence_notice(self.student, [])
